tube_rack_1p5ml:
// Bench rack for 1.5 mL microcentrifuge tubes - a solid block with a vertical grid of
// through-bore holes, floor and open top. NOVEL general part.
//

tube   = 11.2;
bore   = 16;
height = 30;
width  = 106;
rows   = 4;
cols   = 6;

$fn = 96;

sr     = tube / 2 + 2;          // outer radius of the sleeve
L      = bore * 2 + 2;          // length of a sleeve through a bore
foot   = height * 0.3;          // thickness of the foot plate

difference() {
    cube([width, rows * bore, height]);
    translate([0, rows * bore / 2 - bore / 2, -1]) cube([width, bore, height + 2]);   // foot plate
    for (y = [0 : rows - 1])
        for (x = [0 : cols - 1])
            translate([x * width / cols - width / 2, y * bore - bore / 2, -1]) cylinder(h = L, r = sr);   // sleeves
}

conical_rack_50ml:
// A tube rack for Falcon-style conical tubes, printed upside down and flipped. NOVEL general part.
//

tube_d = 30.5;
spac   = 40;
y_span = 2 * spac / 2;
wall_h = 70;

$fn = 72;

plate_w = tube_d + 2 * spac;
short_x = tube_d / 2 + 1;

difference() {
    union() {
        translate([-plate_w / 2, -y_span / 2, 0]) cube([plate_w, y_span, 4]);
        for (x = [-(plate_w / 2 - short_x), plate_w / 2 - short_x])
            translate([x, 0, 0]) cube([short_x, y_span, wall_h]);
    }
    for (x = [-plate_w / 2 + spac, plate_w / 2 - spac], i = [0, 1])
        translate([x, -y_span / 2 + i * spac, -1]) cylinder(h = y_span + 2, d = tube_d);
}

slide_drying_rack:
// Drying rack for microscope slides - a solid base with a set of parallel slots that stand
// a number of microscope slides upright on their long edges, for drying them after use.
// NOVEL general laboratory part.
//

slide  = 75;
width  = 25;
height = 1;

base_x = 90;
base_y = 45;
base_z = 20;

slot_l = base_x;
slot_w = 1.6;
slot_h = 10;

slot_c = 3.5;

$fn = 96;

difference() {
    translate([-base_x / 2, -base_y / 2, 0]) cube([base_x, base_y, base_z]);
    for (x = [base_x * / 2 - slot_c * (slot_c + slot_l) / 2 : slot_c : base_x * / 2])
        translate([x, -base_y / 2, -1]) cube([slot_l, base_y, slot_h]);
}

pcr_tube_rack_sbs:
// PCR tube rack / media storage - a flat block with a grid of vertical through-bore
// holes for 96 PCR tubes or media, with an orientation feature at one corner. NOVEL general part.
//

tube_r = 6.2;
spc    = 9.0;
rows   = 8;
cols   = 12;
length = spc * cols;
width  = spc * rows;
height = 20;

$fn = 48;

first_h = 14.38;
first_w = 11.24;
corner_chamfer = 5;

difference() {
    translate([-length / 2, -width / 2, 0]) cube([length, width, height]);
    for (x = [0 : cols - 1])
        for (y = [0 : rows - 1])
            translate([spc * x - length / 2, spc * y - width / 2, -1]) cylinder(h = height + 2, d = tube_r);
    translate([-(spc * (cols - 1)) / 2 - length / 2, -(spc * (rows - 1)) / 2 - width / 2, -1])
        cube([spc * cols, spc * rows, 3]);                 // floor grid pattern
    translate([-(spc * (cols - 1)) / 2 - length / 2 + first_h - spc / 2,
               -(spc * (rows - 1)) / 2 - width / 2 + first_w - spc / 2, -1])
        cube([spc, spc, 3]);                             // A1 position marker
    rotate([-45, 0, 0]) translate([-(spc * (cols - 1)) / 2 - length / 2 + first_h - spc / 2,
                                   -(spc * (rows - 1)) / 2 - width / 2 + first_w - spc / 2 + 1, -1])
        cube([spc, corner_chamfer, corner_chamfer]);       // orientation feature
}

gel_comb_10well:
// A gel comb for pouring horizontal agarose gels, a flat plate with a spine and multiple
// rectangular teeth hanging downward from one edge, for casting wells in a gel cast.
//

spine_l   = 70;
spine_w   = 12;
teeth     = 10;
tooth_w   = 5;
tooth_h   = 12;
gap       = 1.5;
thickness = 1.5;

$fn = 96;

spine_h = thickness * 2;                 // make the spine tall so it overhangs the build plate

difference() {
    union() {
        translate([-spine_l / 2, 0, 0]) cube([spine_l, spine_w, spine_h]);      // spine
        for (i = [0 : teeth - 1])
            translate([spine_l * i / teeth - tooth_w / 2, -spine_w / 2, 0])
                cube([tooth_w, tooth_h, spine_h]);                               // teeth
    }
    translate([0, 0, -1]) cube([spine_l + 2, spine_w + 2, thickness * 3]);     // clear the bottom
}

micropestle_1p5ml:
// Pestle for tissue grinding in a microcentrifuge tube - a cylindrical handle followed by a
// tapered cone, with a rounded tip, fording a groove pattern in the base. NOVEL general part.
//

tube_d   = 8;
cone_d1  = 8;
cone_d2  = 3;
tip_d    = 3;
handle_z = 45;
total_z  = 62;

$fn = 96;

groove_w = 2;
groove_t = 1;
groove_c = tube_d / 3;

difference() {
    union() {
        cylinder(h = handle_z, d = tube_d);
        resize([tube_d, (cone_d2 - cone_d1) / 3, handle_z]) translate([0, 0, handle_z / 3]) cylinder(h = total_z, d1 = cone_d1, d2 = cone_d2);
        translate([0, 0, total_z]) sphere(d = tip_d);
    }
    translate([0, 0, -1]) cylinder(h = handle_z + 2, d = tube_d + 2 * groove_c);                 // grooves
    for (z = [10, 15, 20, 25])
        translate([0, 0, z]) rotate([0, 90, 0]) rectangle(d1 = groove_w, d2 = tube_d + 2 * groove_c);  // grooves
}

lab_funnel_60mm:
// Small lab funnel / siphon - a spouted tube with a conical top, open at both ends. NOVEL general part.
//

spout_d   = 10;
spout_h   = 20;
cone_d_in = 10;
cone_d_out= 60;
wall      = 1.6;

$fn = 96;

difference() {
    union() {
        translate([0, 0, -1]) cylinder(h = spout_h + 1, d = spout_d);                 // spout (tube)
        translate([0, 0, spout_h]) rotate([0, 90, 0]) cylinder(h = spout_d + 2, d = 6);  // flange
    }
    translate([0, 0, -1]) cylinder(h = spout_h + 2, d = spout_d - 2 * wall);            // hollow the spout
    translate([0, 0, spout_h]) rotate([0, 90, 0]) cylinder(h = spout_d, d = 6);         // flange pocket

    translate([0, 0, spout_h]) rotate([-90, 0, 0]) cylinder(h = cone_d_in + 2, d = cone_d_in);   // cone
    translate([0, 0, spout_h + cone_d_in]) rotate([-90, 0, 0])
        cylinder(h = cone_d_out, d = cone_d_out + 2);                                        // cone flange
}

seed_sowing_template:
// Sowing template - a flat disc with a through-hole grid that sits inside a round petri
// dish, with an orientation notch. NOVEL general part.
//

dish_d = 90;
template_d = 85;
template_t = 2;
grid_size = 7;
through_d = 3;
centre_dist = 9;
notch_w = 10;
notch_d = 4;

$fn = 100;

inner_r = dish_d / 2;
outer_r = template_d / 2;
grid_v = template_t / 2;

difference() {
    translate([-inner_r, 0, 0]) cylinder(h = template_t, r = outer_r);
    translate([0, -outer_r, grid_v]) rotate([0, 90, 0]) cylinder(h = 2 * outer_r, r = inner_r);
    for (i = [0 : grid_size - 1])
        for (j = [0 : grid_size - 1])
            translate([i * centre_dist - template_d / 2, j * centre_dist - template_d / 2, 0])
                cylinder(h = template_t + 2, d = through_d);
    translate([0, outer_r + 1.5, 0]) rotate([-90, 0, 0]) linear_extrude(notch_d) rectangle(width = notch_w, height = 2 * outer_r);
}

dshaft_knob_6mm:
// Knob for a hotplate stirrer - a round button with an overhang and a finger grip, to set a
// temperature or speed. NOVEL general part.
//

shaft_d   = 6;
d         = 30;
h         = 15;
bore_h    = 12;
flat      = 4.7;
groove_w  = 2;
pointer_w = 1.5;
pointer_t = 1;

$fn = 96;

difference() {
    cylinder(h = h, d = d);
    translate([0, 0, h / 3]) rotate([-90, 0, 0]) cylinder(h = d + 2, d = shaft_d);   // overhang
    translate([0, 0, -1]) rotate([0, 90, 0]) cylinder(h = bore_h + 2, d = shaft_d * 2);  // blind bore
    for (i = [0 : 17])
        rotate([0, 0, i * 360 / 18]) translate([d / 2 - 1, 0, 0]) cylinder(h = h + 2, d = groove_w);   // grip grooves
    translate([0, 0, h / 2]) rotate([90, 0, 0]) linear_extrude(pointer_t) polygon([[-1.5, -1], [1.5, -1], [0, pointer_w]]);   // pointer
    translate([0, 0, h / 2]) rotate([90, 0, 0]) linear_extrude(-1) polygon([[-flat / 2, 0], [flat / 2, 0], [shaft_d / 2, pointer_w / 2], [shaft_d / 2, -pointer_w / 2]]);   // D slot
}

pcr_tube_adapter:
// Adapter sleeve for a 0.2 mL PCR tube in a 1.5 mL rack hole - lines up the tube axis with a
// bore through a different-size tube. NOVEL general part.
//

src   = 13;
thick = 1.5;
bore  = 6.2;
od    = 10.8;

$fn = 72;

collar_h = thick;
sleeve_h = 21.5;

difference() {
    union() {
        cylinder(h = collar_h, d = src);
        cylinder(h = sleeve_h, d = od);
    }
    translate([0, 0, -1]) cylinder(h = sleeve_h + 2, d = bore);
}

hose_barb_reducer_8_5:
// Hose barb reducer - joins two tube sizes with a bore. NOVEL general part.
//

bore   = 3;
in_d1  = 8;
in_d2  = 5;
length = 41;

$fn = 96;

H = in_d1 / 2 - bore / 2;
G = in_d2 / 2 - bore / 2;

difference() {
    union() {
        cylinder(h = H, d = in_d1);
        cylinder(h = H, d = in_d2);
        translate([0, 0, -1]) cylinder(h = length + 2, d = bore);
    }
    translate([0, 0, H]) cylinder(h = length, d = in_d1);
    translate([0, 0, -1]) cylinder(h = length + 2, d = bore);
}

rod_tubing_clip:
// Snap-on tube clip - lines a piece of flexible tubing up against a lab stand rod
// (a round shaft) by snapping onto both a round rod and a round tube. NOVEL general part.
//

rod_d   = 12.7;
wall    = 3;
tubing_d= 6;
bridge_w= 6;
height  = 10;

$fn = 96;

ring_d(bore, w) {
    difference() {
        cylinder(h = height, d = bore + 2 * w);
        translate([0, 0, -1]) cylinder(h = height + 2, d = bore);
    }
}

tube_d(bore, w) {
    difference() {
        cylinder(h = height, d = bore + 2 * w);
        translate([0, 0, -1]) cylinder(h = height + 2, d = bore);
    }
}

bridge(w) {
    difference() {
        rectangle(h = height, w = w);
        translate([0, -1.5, 0]) rectangle(h = height + 3, w = 2);     // round the ends
    }
}

difference() {
    union() {
        ring_d(rod_d, wall);
        translate([15, 0, 0]) ring_d(tubing_d, wall);
        bridge(-6);
    }
    translate([-1, -5, 0]) cube([2, 10, height]);                   // remove the rod ring left
}

stirrer_fan_housing:
// Magnetic stirrer - an upside-down open box that covers a PC case fan to make a stirring
// surface, with an open top and four upright walls. NOVEL general laboratory device.
//

inner_d  = 90;
height   = 40;
top_t    = 2;
wall_t   = 2.5;
screw_p  = 71.5;
screw_d  = 4.5;
notch_w  = 12;
notch_h  = 8;

$fn = 48;

difference() {
    union() {
        cylinder(h = top_t, d = inner_d);              // top plate
        for (x = [-inner_d / 2, inner_d / 2])
            translate([x, 0, 0]) cylinder(h = height + top_t, d = wall_t);   // four walls
    }
    translate([0, 0, top_t]) cylinder(h = height, d = inner_d + 2 * wall_t);   // hollow out the walls
    for (x = [-(inner_d / 2 - screw_p / 2), inner_d / 2 - screw_p / 2])
        translate([x, 0, -1]) cylinder(h = top_t + 2, d = screw_d);           // screw holes
    translate([-inner_d / 2 + notch_w / 2, 0, height * 3 / 4])
        cube([notch_w, inner_d, notch_h]);                                        // power cable notch
}

nema17_motor_bracket:
// L-shaped mount for a NEMA 17 stepper motor, with a vertical base plate and a vertical
// motor plate. NOVEL general part.
//

base_t   = 5;
motor_h  = 50;
gusset_t = 5;

base_x = 25;
base_y = 45;
motor_y = 5;

vertical_through_d = 4.5;
m3_d = 3.4;
m3_pitch = 7.6;

$fn = 96;

base           = cube([2 * base_x, base_y, base_t]);
vertical_plate = cube([2 * base_x, motor_y, motor_h]);
motor_plate    = translate([0, base_y, 0]) (cube([2 * base_x, motor_y, motor_h]));

difference() {
    union() {
        base;
        vertical_plate;
        motor_plate;
    }
    for (x = [-base_x, base_x])
        translate([x, 0, -1]) cylinder(h = base_t + 2, d = vertical_through_d);
    for (y = [base_y, base_y + motor_y])
        translate([0, y, -1]) cylinder(h = motor_h + 2, d = vertical_through_d);
    translate([0, base_y - 1, motor_h / 2]) cylinder(h = motor_y + 2, d1 = m3_d * 2, d2 = m3_d * 2 + m3_pitch);
    for (i = [0, 1, 2, 3])
        rotate([0, 90 * i, 0])
            translate([base_x * 0.5 - 1.5, base_y + motor_y / 2, motor_h / 2])
                cylinder(h = motor_y + 2, d = m3_d * 2);
    for (x = [-base_x, base_x])
        for (z = [0, base_t])
            gusset(x, z);
}

gusset(x, z) {
    translate([x, -5, z]) cube([20, 10, gusset_t]);
}

enclosure_box_and_lid:
// Two-part enclosure - a box with an overhang-ing lid, for a small surface mount
// electronic board (Arduino, sensor board, etc.). NOVEL general part.
//

box     = [70, 50, 30];
wall    = 2;
floor   = 2;
lid_wall = 1.5;
lip_h   = 4;

$fn = 64;

difference() {
    union() {
        translate([-box[0] / 2, -box[1] / 2, 0]) cube([box[0], box[1], wall]);
        translate([-box[0] / 2, -box[1] / 2, 0]) cube([box[0], floor, box[2]]);
    }
    translate([-box[0] / 2, -box[1] / 2, -1]) cube([box[0], box[1], wall + 2]);     // hollow for the interior
}

union() {
    translate([box[0] / 2 + 10, -box[1] / 2, 0]) cube([box[0], box[1], lip_h]);
    translate([box[0] / 2 + 10, -box[1] / 2, -1]) cube([box[0], box[1], lip_h + 2]);
}

difference() {
    translate([box[0] / 2 + 10, -box[1] / 2, lip_h]) cube([65.6, 45.6, -1.4]);      // the lip (overhang)
    translate([box[0] / 2 + 10, -box[1] / 2, -3]) cube([69.2, 49.2, 2]);            // the plate
}

mini_gel_tank:
// Buffer tank for a mini horizontal gel electrophoresis box - an open-top rectangular
// tank with a solid platform in the middle dividing it into two buffer chambers, with
// electrode lead-in holes through each end wall. NOVEL general laboratory part.
//

inner_X = 120;
inner_Y = 70;
inner_Z = 40;
wall    = 3;
floor   = 3;

$fn = 96;

platform = 60;
height   = 10;

difference() {
    cube([inner_X + 2 * wall, inner_Y + 2 * wall, inner_Z + wall]);
    translate([wall, wall, wall]) cube([inner_X, inner_Y, height]);                 // tank minus top and floor
    translate([inner_X / 2 - platform / 2, wall, -1]) cube([platform, inner_Y, height + 2]);  // platform
    for (x = [-inner_X / 2, inner_X / 2])
        translate([x, 0, inner_Z / 2]) cylinder(h = wall + 1, d = 2);            // electrode holes
}
